export function placeGhost(ghost, image, big, small, bigRadius, imageUrl) {
  // Le calque fantôme est posé UNE fois à la taille finale (grande) ; le trajet n'utilise
  // ensuite que transform + clip-path, gérés par la carte graphique, sans mise en page.
  Object.assign(ghost.style, { left: `${big.left}px`, top: `${big.top}px`, width: `${big.width}px`, height: `${big.height}px` });
  const scale = Math.max(small.width / big.width, small.height / big.height);
  const cropX = (big.width - small.width / scale) / 2;
  const cropY = (big.height - small.height / scale) / 2;
  const dx = small.left + small.width / 2 - (big.left + big.width / 2);
  const dy = small.top + small.height / 2 - (big.top + big.height / 2);

  // L'image garde sa taille complète, centrée (comme background-size: cover) ;
  // c'est le recadrage du calque qui choisit la partie visible.
  let imageScale = 1;
  const probe = new Image();
  probe.src = imageUrl; // déjà en cache : la carte l'affiche
  if (probe.naturalWidth) {
    const bigCover = Math.max(big.width / probe.naturalWidth, big.height / probe.naturalHeight);
    const smallCover = Math.max(small.width / probe.naturalWidth, small.height / probe.naturalHeight);
    const width = probe.naturalWidth * bigCover;
    const height = probe.naturalHeight * bigCover;
    Object.assign(image.style, { left: `${(big.width - width) / 2}px`, top: `${(big.height - height) / 2}px`, width: `${width}px`, height: `${height}px`, right: "auto", bottom: "auto", backgroundSize: "100% 100%" });
    imageScale = smallCover / (bigCover * scale);
  }
  return {
    ghostSmall: { transform: `translate(${dx}px, ${dy}px) scale(${scale})`, clipPath: `inset(${cropY}px ${cropX}px round ${CARD_RADIUS / scale}px)` },
    ghostBig: { transform: "translate(0px, 0px) scale(1)", clipPath: `inset(0px 0px round ${bigRadius}px)` },
    imageSmall: { transform: `scale(${imageScale})` },
    imageBig: { transform: "scale(1)" },
  };
}

