const prepareReturn = useCallback((index, topOffset) => {
  const rail = railRef.current;
  const card = cardRefs.current[index];
  if (!card) return null;
  // 1. Dans le rail horizontal : alignée sur un point d'accroche, sans animation.
  const padding = parseFloat(getComputedStyle(rail).scrollPaddingLeft) || 0;
  const railBounds = rail.getBoundingClientRect();
  let bounds = card.getBoundingClientRect();
  if (bounds.left < railBounds.left || bounds.right > railBounds.right) {
    rail.scrollTo({ left: Math.max(0, rail.scrollLeft + bounds.left - railBounds.left - padding), behavior: "instant" });
  }
  // 2. Dans la page : entièrement visible sous la barre de navigation.
  bounds = card.getBoundingClientRect();
  const margin = 16;
  const room = innerHeight - topOffset - margin * 2;
  let shift = 0;
  if (bounds.height > room || bounds.top < topOffset + margin) shift = bounds.top - topOffset - margin;
  else if (bounds.bottom > innerHeight - margin) shift = bounds.bottom - innerHeight + margin;
  if (shift) scrollToY(scrollY + shift, { immediate: true }); // Lenis.scrollTo(..., { immediate, force })
  return card;
}, [scrollToY]);

