const close = useCallback(() => {
  if (closingRef.current) return;
  closingRef.current = true;
  const root = rootRef.current;
  videoRef.current?.pause();
  const topOffset = parseFloat(root.style.getPropertyValue("--story-top")) || 0;
  const big = mediaRef.current.getBoundingClientRect();
  const radius = parseFloat(getComputedStyle(mediaRef.current).borderTopLeftRadius) || 22;
  const card = prepareReturn(indexRef.current, topOffset); // place la carte À L'ÉCRAN, d'un coup, derrière le voile
  if (prefersReducedMotion() || !card) { root.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 200, fill: "both" }).finished.then(onClosed); return; }
  card.classList.add("is-story-source");
  const small = card.getBoundingClientRect();              // mesurée APRÈS le placement
  const f = placeGhost(ghostRef.current, ghostImageRef.current, big, small, radius, imageUrl);
  flushSync(() => setPhase("closing"));                    // toute la mise en page AVANT le premier pas
  requestAnimationFrame(() => {
    const timing = { duration: 820, easing: "cubic-bezier(.16, 1, .3, 1)", fill: "both" };
    backdropRef.current.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 520, delay: 300, easing: "cubic-bezier(.4, 0, .2, 1)", fill: "both" });
    ghostImageRef.current.animate([f.imageBig, f.imageSmall], timing);
    ghostRef.current.animate([f.ghostBig, f.ghostSmall], timing).finished
      .then(() => { card.classList.remove("is-story-source"); return ghostRef.current.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 180, fill: "forwards" }).finished; })
      .then(onClosed).catch(onClosed);
  });
}, [onClosed, prepareReturn]);

