.priority-story { position: fixed; inset: 0; z-index: 95; }
.priority-story__backdrop { position: absolute; inset: 0; overflow: hidden; background: #06140f; }
/* Fantôme : seul élément qui voyage ; déplacé par la carte graphique. */
.priority-story__ghost { position: fixed; top: 0; left: 0; z-index: 2; width: 0; height: 0; overflow: hidden; visibility: hidden; transform-origin: center; pointer-events: none; will-change: transform, clip-path; }
.priority-story__ghost-image { position: absolute; inset: 0; background: var(--story-image) center / cover no-repeat; transform-origin: center; will-change: transform; }
.priority-story[data-phase="opening"] .priority-story__ghost,
.priority-story[data-phase="closing"] .priority-story__ghost { visibility: visible; }
.priority-story[data-phase="opening"] .priority-story__media,
.priority-story[data-phase="closing"] .priority-story__media { visibility: hidden; }
.priority-story[data-phase="closing"] .priority-story__bar,
.priority-story[data-phase="closing"] .priority-story__body { animation: story-out .26s ease forwards; }
/* Le contenu monte en cascade après l'arrivée de l'image. */
.story-rise { animation: story-rise .9s cubic-bezier(.16, 1, .3, 1) both; animation-delay: calc(var(--story-delay, 430ms) + var(--i, 0) * 70ms); }
@keyframes story-rise { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: none; } }
@keyframes story-out { to { opacity: 0; transform: translateY(10px); } }
/* La carte d'origine se cache pendant le trajet (c'est le fantôme qu'on voit). */
.is-story-source { visibility: hidden; }
/* Seule la barre de navigation passe devant la vue. */
html.is-priority-story-open .topbar { z-index: auto; }
html.is-priority-story-open .site-header-slot { z-index: 96; }
html.is-priority-story-open .sea-header-panel.is-scroll-nav.is-scroll-nav-hidden { transform: none; opacity: 1; pointer-events: auto; }
